<template><div class="sound-controller-wrapper"><button :class="['sound-controller',{playing:bgmEnabled}]" @click="toggleBgm" :title="bgmEnabled?t('bgmClose'):t('bgmPlay')"><div class="record-disc"><div class="record-center"/><div v-if="bgmEnabled" class="music-notes"><span>♪</span><span>♫</span></div></div><div v-if="!bgmEnabled" class="mute-slash"/></button><button v-if="bgmEnabled" class="next-song-btn" @click.stop="nextBgm" :title="t('nextSong')">▶</button></div></template>
<script setup>import {useSound,useLang} from '../contexts/app'; import './SoundController.css'; const {bgmEnabled,toggleBgm,nextBgm}=useSound(); const {t}=useLang();</script>
